import asyncio, socket

class EventMeshProtocol(asyncio.Protocol):
    def __init__(self, broadcast_channel):
        self.channel = broadcast_channel
        self.transport = None

    def connection_made(self, transport):
        self.transport = transport
        self.transport.set_write_buffer_limits(high=65536)

    def data_received(self, data: bytes):
        # Zero-copy parsing e despacho em milissegundos
        if data.startswith(b'SYNC:'):
            self.channel.dispatch_fast(data[5:])
            self.transport.write(b'ACK\n')
